const express = require('express');
const jwt = require('jsonwebtoken');
const AWS = require('aws-sdk');

const app = express();
app.use(express.json());

const JWT_SECRET = process.env.JWT_SECRET || 'dev-secret-key';
const dynamodb = new AWS.DynamoDB.DocumentClient();

// Middleware to verify JWT tokens
function authenticateToken(req, res, next) {
  const authHeader = req.headers['authorization'];
  const token = authHeader && authHeader.split(' ')[1];
  if (!token) return res.sendStatus(401);

  jwt.verify(token, JWT_SECRET, { algorithms: ['HS256', 'HS384', 'HS512', 'RS256'] }, (err, user) => {
    if (err) return res.sendStatus(403);
    req.user = user;
    next();
  });
}

// User profile endpoint
app.get('/api/v1/users/:userId/profile', authenticateToken, async (req, res) => {
  try {
    const result = await dynamodb.get({
      TableName: 'Users',
      Key: { userId: req.params.userId }
    }).promise();
    res.json(result.Item);
  } catch (err) {
    res.status(500).json({ error: 'Internal server error' });
  }
});

// Role update endpoint - intended for admin use only
app.put('/api/v1/users/:userId/role', authenticateToken, async (req, res) => {
  // Check if requesting user has admin role from JWT claims
  if (req.user.role !== 'admin') {
    return res.status(403).json({ error: 'Insufficient privileges' });
  }

  const { role } = req.body;
  const allowedRoles = ['viewer', 'editor', 'admin', 'super-admin'];

  if (!allowedRoles.includes(role)) {
    return res.status(400).json({ error: 'Invalid role' });
  }

  try {
    await dynamodb.update({
      TableName: 'Users',
      Key: { userId: req.params.userId },
      UpdateExpression: 'SET #r = :role, updatedAt = :ts',
      ExpressionAttributeNames: { '#r': 'role' },
      ExpressionAttributeValues: {
        ':role': role,
        ':ts': new Date().toISOString()
      }
    }).promise();
    res.json({ success: true, userId: req.params.userId, newRole: role });
  } catch (err) {
    res.status(500).json({ error: 'Failed to update role' });
  }
});

// Token refresh endpoint
app.post('/api/v1/auth/refresh', authenticateToken, async (req, res) => {
  // Issue new token with same claims - vulnerability: copies unvalidated claims
  const newToken = jwt.sign(
    { userId: req.user.userId, role: req.user.role, email: req.user.email },
    JWT_SECRET,
    { expiresIn: '24h', algorithm: 'HS256' }
  );
  res.json({ token: newToken });
});

// Health check
app.get('/health', (req, res) => {
  res.json({ status: 'healthy', version: '2.4.1' });
});

app.listen(3000, '0.0.0.0', () => {
  console.log('User service running on port 3000');
});
